const test = require('node:test');
const assert = require('node:assert/strict');
const { previewEdit } = require('../src/queue-preview.cjs');

test("no arguments omitted count and explicit undefined are distinct", () => {
  const queue = ['oak', 'pine', 'elm', 'ash'];
  assert.deepEqual(previewEdit(queue, []), {next: queue, removed: []});
  assert.deepEqual(previewEdit(queue, [1]), {next: ['oak'], removed: ['pine', 'elm', 'ash']});
  assert.deepEqual(previewEdit(queue, [1, undefined, 'cedar']), {next: ['oak', 'cedar', 'pine', 'elm', 'ash'], removed: []});
  assert.deepEqual(previewEdit(queue, [undefined]), {next: [], removed: queue});
  assert.deepEqual(queue, ['oak', 'pine', 'elm', 'ash']);
});

test("negative starts and oversized starts follow splice rules", () => {
  assert.deepEqual(previewEdit(['a', 'b', 'c', 'd'], [-2, 1, 'x']), {next: ['a', 'b', 'x', 'd'], removed: ['c']});
  assert.deepEqual(previewEdit(['a', 'b'], [-99, 1]), {next: ['b'], removed: ['a']});
  assert.deepEqual(previewEdit(['a', 'b'], [99, 2, 'x']), {next: ['a', 'b', 'x'], removed: []});
  assert.deepEqual(previewEdit(['a', 'b'], [0, Infinity, 'x']), {next: ['x'], removed: ['a', 'b']});
});

test("preview copies the queue but retains sparse removed entries", () => {
  const queue = ['oak', , 'elm'];
  const args = [1, 2];
  const result = previewEdit(queue, args);
  assert.deepEqual(result.next, ['oak']);
  assert.deepEqual(result.removed, [, 'elm']);
  assert.equal(0 in result.removed, false);
  assert.equal(1 in queue, false);
  assert.deepEqual(args, [1, 2]);
  assert.notEqual(previewEdit(queue, []).next, queue);
});

